sp_widget.css:
.analytics-page {
    max-width: 1080px;
    margin: 0 auto;
    padding: 28px;
    color: #102a56;
}


/* =========================================
   HEADER
========================================= */

.analytics-header {

    background: linear-gradient(
        135deg,
        #f4f3ff,
        #eef1ff
    );

    border: 1px solid #dfe3ff;
    border-radius: 18px;

    padding: 30px;

    display: flex;
    justify-content: space-between;
    align-items: center;

    margin-bottom: 22px;
}


.eyebrow {

    font-size: 11px;

    letter-spacing: 2px;

    font-weight: 700;

    color: #5267e8;
}


.analytics-header h1 {

    margin: 8px 0 5px;

    font-size: 28px;

    color: #082b62;
}


.analytics-header p {

    margin: 0 0 12px;

    color: #66789b;
}


.company-label {

    display: inline-block;

    padding: 6px 10px;

    border-radius: 7px;

    background: #eef1ff;

    color: #5267e8;

    font-size: 12px;

    font-weight: 600;
}


/* =========================================
   BUTTON
========================================= */

.btn {

    display: inline-block;

    padding: 11px 18px;

    border-radius: 9px;

    text-decoration: none;

    font-size: 13px;

    font-weight: 600;
}


.btn-secondary {

    border: 1px solid #cbd5ef;

    background: white;

    color: #3156e8;
}


/* =========================================
   KPI GRID
========================================= */

.kpi-grid {

    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 14px;

    margin-bottom: 20px;
}


.kpi-card {

    background: white;

    border: 1px solid #dce3f0;

    border-radius: 14px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 14px;

    box-shadow:
        0 5px 18px
        rgba(40, 65, 110, 0.05);
}


.kpi-icon {

    width: 42px;

    height: 42px;

    border-radius: 11px;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 18px;

    font-weight: 700;
}


.kpi-icon.purple {

    background: #eef0ff;

    color: #5267e8;
}


.kpi-icon.blue {

    background: #edf5ff;

    color: #2875d6;
}


.kpi-icon.green {

    background: #eaf8f0;

    color: #16834a;
}


.kpi-icon.orange {

    background: #fff6e5;

    color: #d88900;
}


.kpi-label {

    font-size: 11px;

    color: #7a89a5;

    margin-bottom: 5px;
}


.kpi-value {

    font-size: 24px;

    font-weight: 700;

    color: #102e61;
}


/* =========================================
   ANALYTICS GRID
========================================= */

.analytics-grid {

    display: grid;

    grid-template-columns:
        repeat(2, 1fr);

    gap: 18px;

    margin-bottom: 18px;
}


.analytics-card {

    background: white;

    border: 1px solid #dce3f0;

    border-radius: 16px;

    padding: 24px;

    box-shadow:
        0 6px 20px
        rgba(40, 65, 110, 0.05);

    margin-bottom: 18px;
}


.card-header {

    margin-bottom: 22px;
}


.card-header h2 {

    margin: 0 0 5px;

    color: #173b70;

    font-size: 17px;
}


.card-header p {

    margin: 0;

    color: #8290aa;

    font-size: 12px;
}


/* =========================================
   STATUS / LOCATION
========================================= */

.status-row,
.location-row {

    margin-bottom: 18px;
}


.status-info,
.location-name {

    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 7px;

    font-size: 13px;

    color: #42577a;
}


.status-info strong,
.location-name strong {

    color: #173b70;
}


.progress {

    height: 7px;

    background: #edf0f7;

    border-radius: 10px;

    overflow: hidden;
}


.progress-bar {

    height: 100%;

    background: #5267e8;

    border-radius: 10px;

    transition:
        width 0.3s ease;
}


.location-bar {

    background: #2875d6;
}


/* =========================================
   PIPELINE
========================================= */

.pipeline-card {

    margin-bottom: 18px;
}


.pipeline {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 8px;

    overflow-x: auto;

    padding: 5px 0;
}


.pipeline-step {

    min-width: 105px;

    text-align: center;
}


.pipeline-number {

    width: 54px;

    height: 54px;

    margin: 0 auto 8px;

    border-radius: 50%;

    background: #eef1ff;

    color: #5267e8;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 17px;

    font-weight: 700;
}


.pipeline-label {

    font-size: 11px;

    color: #647694;

    white-space: nowrap;
}


.pipeline-arrow {

    color: #a3aec3;

    font-size: 18px;

    flex-shrink: 0;
}


/* =========================================
   OUTCOME
========================================= */

.outcome-grid {

    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 14px;
}


.outcome-item {

    background: #f8f9ff;

    border: 1px solid #e4e8f8;

    border-radius: 12px;

    padding: 18px;

    display: flex;

    align-items: center;

    gap: 14px;
}


.outcome-icon {

    width: 40px;

    height: 40px;

    border-radius: 10px;

    background: #eaf8f0;

    color: #16834a;

    display: flex;

    align-items: center;

    justify-content: center;

    font-weight: 700;
}


.outcome-item span {

    display: block;

    font-size: 11px;

    color: #7b89a3;

    margin-bottom: 4px;
}


.outcome-item strong {

    font-size: 20px;

    color: #173b70;
}


/* =========================================
   EMPTY STATE
========================================= */

.empty-state {

    padding: 25px;

    text-align: center;

    color: #8793a8;

    font-size: 13px;
}


/* =========================================
   ERROR
========================================= */

.error-message {

    padding: 18px;

    background: #fff2f2;

    border: 1px solid #ffd2d2;

    border-radius: 10px;

    color: #c62828;

    margin-bottom: 20px;
}


/* =========================================
   FOOTER
========================================= */

.analytics-footer {

    text-align: center;

    color: #8995aa;

    font-size: 12px;

    padding: 10px;
}


/* =========================================
   RESPONSIVE
========================================= */

@media (max-width: 900px) {

    .kpi-grid {

        grid-template-columns:
            repeat(2, 1fr);

    }

}


@media (max-width: 700px) {

    .analytics-header {

        flex-direction: column;

        align-items: flex-start;

        gap: 20px;

    }


    .analytics-grid {

        grid-template-columns: 1fr;

    }


    .kpi-grid {

        grid-template-columns: 1fr;

    }


    .outcome-grid {

        grid-template-columns: 1fr;

    }

}

sp_widget.script:
(function() {

    // =====================================================
    // CURRENT TEST RECRUITER
    // =====================================================

    // We are intentionally using the same sample recruiter
    // until the complete recruiter portal is finished.

    data.recruiter_name = 'Ananya Mehta';
    data.recruiter_id = 'RCR001';


    // =====================================================
    // CURRENT TEST COMPANY
    // =====================================================

    // TechNova Solutions - CMP001

    var companySysId =
        'e9268662acd303107f44b432e349694b';


    // =====================================================
    // INITIAL DATA
    // =====================================================

    data.error = '';

    data.company = {
        name: 'TechNova Solutions',
        id: 'CMP001'
    };


    data.kpi = {

        total_opportunities: 0,
        active_opportunities: 0,

        total_applications: 0,
        shortlisted: 0,

        total_interviews: 0,
        selected: 0,

        offers: 0,
        placements: 0

    };


    data.application_status = [];

    data.locations = [];

    data.pipeline = {

        applications: 0,
        shortlisted: 0,
        interviews: 0,
        selected: 0,
        offers: 0,
        placements: 0

    };


    data.outcomes = {

        selected: 0,
        on_campus: 0,
        off_campus: 0

    };


    // =====================================================
    // GET COMPANY
    // =====================================================

    var companyGR =
        new GlideRecord(
            'x_snc_campus360_company_master'
        );


    if (!companyGR.get(companySysId)) {

        data.error =
            'Company record could not be found.';

        return;

    }


    data.company.name =
        companyGR.getValue('company_name');

    data.company.id =
        companyGR.getValue('company_id');


    // =====================================================
    // 1. PLACEMENT OPPORTUNITIES
    // =====================================================

    var oppGR =
        new GlideRecord(
            'x_snc_campus360_placement_opportunity'
        );


    oppGR.addQuery(
        'company',
        companySysId
    );

    oppGR.query();


    var opportunityIds = [];

    var locationMap = {};

    while (oppGR.next()) {

        data.kpi.total_opportunities++;

        opportunityIds.push(
            oppGR.getUniqueValue()
        );


        // ---------------------------------------------
        // ACTIVE / OPEN OPPORTUNITIES
        // ---------------------------------------------

        var oppStatus =
            oppGR.getValue('status');


        if (
            oppStatus == 'Open' ||
            oppStatus == 'open'
        ) {

            data.kpi.active_opportunities++;

        }


        // ---------------------------------------------
        // LOCATION ANALYTICS
        // ---------------------------------------------

        var location =
            oppGR.getValue('location');


        if (location) {

            if (!locationMap[location]) {

                locationMap[location] = 0;

            }

            locationMap[location]++;

        }

    }


    // =====================================================
    // CONVERT LOCATION MAP TO ARRAY
    // =====================================================

    for (var locationName in locationMap) {

        data.locations.push({

            name: locationName,

            count:
                locationMap[locationName]

        });

    }


    // =====================================================
    // 2. STUDENT APPLICATIONS
    // =====================================================

    if (opportunityIds.length > 0) {

        var appGR =
            new GlideRecord(
                'x_snc_campus360_student_application'
            );


        appGR.addQuery(
            'opportunity',
            'IN',
            opportunityIds.join(',')
        );

        appGR.query();


        var applicationStatusMap = {};


        while (appGR.next()) {

            data.kpi.total_applications++;

            data.pipeline.applications++;


            // -----------------------------------------
            // APPLICATION STATUS
            // -----------------------------------------

            var applicationStatus =
                appGR.getDisplayValue(
                    'application_status'
                );


            if (!applicationStatus) {

                applicationStatus = 'Unknown';

            }


            if (
                !applicationStatusMap[
                    applicationStatus
                ]
            ) {

                applicationStatusMap[
                    applicationStatus
                ] = 0;

            }


            applicationStatusMap[
                applicationStatus
            ]++;


            // -----------------------------------------
            // SHORTLISTED
            // -----------------------------------------

            var shortlisted =
                appGR.getValue(
                    'shortlisted'
                );


            if (
                shortlisted == 'true' ||
                shortlisted == '1'
            ) {

                data.kpi.shortlisted++;

                data.pipeline.shortlisted++;

            }


            // -----------------------------------------
            // OFFER STATUS
            // -----------------------------------------

            var offerStatus =
                appGR.getDisplayValue(
                    'offer_status'
                );


            if (
                offerStatus == 'Offered' ||
                offerStatus == 'offered'
            ) {

                data.kpi.offers++;

                data.pipeline.offers++;

            }

        }


        // =================================================
        // APPLICATION STATUS ARRAY
        // =================================================

        for (
            var statusName in applicationStatusMap
        ) {

            data.application_status.push({

                name: statusName,

                count:
                    applicationStatusMap[
                        statusName
                    ]

            });

        }

    }


    // =====================================================
    // 3. RECRUITER INTERVIEWS
    // =====================================================

    var interviewGR =
        new GlideRecord(
            'x_snc_campus360_recruiter_interview'
        );


    interviewGR.addQuery(
        'company',
        companySysId
    );

    interviewGR.query();


    while (interviewGR.next()) {

        data.kpi.total_interviews++;

        data.pipeline.interviews++;


        // ---------------------------------------------
        // RESULT = SELECTED
        // ---------------------------------------------

        var interviewResult =
            interviewGR.getDisplayValue(
                'result'
            );


        if (
            interviewResult == 'Selected' ||
            interviewResult == 'selected'
        ) {

            data.kpi.selected++;

            data.pipeline.selected++;

        }

    }


    // =====================================================
    // 4. PLACEMENT OUTCOMES
    // =====================================================

    var outcomeGR =
        new GlideRecord(
            'x_snc_campus360_placement_outcome'
        );


    outcomeGR.addQuery(
        'company',
        companySysId
    );

    outcomeGR.query();


    while (outcomeGR.next()) {

        data.kpi.placements++;

        data.pipeline.placements++;


        // ---------------------------------------------
        // OUTCOME TYPE
        // ---------------------------------------------

        var outcomeType =
            outcomeGR.getDisplayValue(
                'outcome_type'
            );


        if (
            outcomeType == 'Selected' ||
            outcomeType == 'selected'
        ) {

            data.outcomes.selected++;

        }


        // ---------------------------------------------
        // PLACEMENT TYPE
        // ---------------------------------------------

        var placementType =
            outcomeGR.getDisplayValue(
                'placement_type'
            );


        if (
            placementType == 'On Campus' ||
            placementType == 'On campus'
        ) {

            data.outcomes.on_campus++;

        }


        if (
            placementType == 'Off Campus' ||
            placementType == 'Off campus'
        ) {

            data.outcomes.off_campus++;

        }

    }


})();
